(function(){'use strict';
const E=window.AdventureEngine,A=window.AdventureArt,$=id=>document.getElementById(id),KEY='castaways-adventure-v3',PREF='castaways-adventure-prefs';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state=E.createGame(),selected=null,player={x:45,y:84},ticket=0,thoughtTimer,captionTimer,revealTimer,completionTimer,saving=true,finalShown=false;
let prefs={captions:false,reduced:matchMedia('(prefers-reduced-motion: reduce)').matches};
try{state=E.restore(JSON.parse(localStorage.getItem(KEY)))||state;const p=JSON.parse(localStorage.getItem(PREF));if(p){prefs.captions=Boolean(p.captions);prefs.reduced=prefs.reduced||Boolean(p.reduced);}}catch(_){}
const drawings={
 shelter:'<path d="m4 53 23-42 30 41M27 11l-3 42M5 52h52M27 11l21-4 12 34" fill="none" stroke-width="4"/>',
 signal:'<path d="M17 58V5M7 58h22M18 6q14-6 32 1l-8 11 7 10q-17-8-31-1" fill="none" stroke-width="3"/>',
 eye:'<path d="M4 32q28-33 56 0-28 33-56 0Z" fill="none"/><circle cx="32" cy="32" r="10" fill="#65704d"/>',
 hand:'<path d="M18 54 9 35q-2-8 5-6l8 9V12q0-7 6-4v20-22q6-7 7 1v21-17q7-4 7 4v16-12q7-1 7 6v19l-7 15Z" fill="#c8ad7d"/>',
 wrong:'<path d="m17 17 30 30m0-30L17 47" fill="none" stroke-width="5"/>',
 done:'<path d="m12 31 13 14 28-31" fill="none" stroke-width="5"/>',
 talk:'<path d="M7 13h48v31H30L17 55V44H7Z" fill="none"/><circle cx="20" cy="28" r="2"/><circle cx="32" cy="28" r="2"/><circle cx="44" cy="28" r="2"/>'
};
function painted(a,cls=''){return `<svg class="painted ${cls}" viewBox="${a.box.join(' ')}" preserveAspectRatio="xMidYMid meet" aria-hidden="true"><image href="${a.file}" width="${a.width}" height="${a.height}"/></svg>`;}
const svg=(id,cls='')=>A.props[id]?painted(A.props[id],cls):id==='fire'?painted(A.states.fire,cls):`<svg class="glyph ${cls}" viewBox="0 0 64 64" aria-hidden="true">${drawings[id]||drawings.eye}</svg>`;
const person=id=>`<span class="actor-shadow"></span>${painted(A.people[id],'actor-painting')}`;
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));saving=true;}catch(_){saving=false;} $('saved').style.color=saving?'#b9bd91':'#d6a177';$('saved').title=saving?'Uloženo v tomto prohlížeči':'Ukládání není dostupné';}
function savePrefs(){document.body.classList.toggle('reduced',prefs.reduced);try{localStorage.setItem(PREF,JSON.stringify(prefs));}catch(_){}}
function label(text){$('action-label').textContent=text;}
function setSelected(id){selected=id;renderInventory();$('cancel-item').hidden=!id;label(id?E.ITEMS[id].name+' → …':E.SCENES.find(s=>s.id===state.scene).name);$('cursor-item').innerHTML=id?svg(id):'';$('cursor-item').style.display=id?'block':'none';}
function showCue(cue,text,items=[]){const aliases={take:items[0]||'hand',combine:items[0]||'loopPole',canvas_recovered:'canvas',crate_open:'axe',wood_cut:'firewood',shelter_built:'shelter',fuel_placed:'firewood',fire_lit:'fire',mast_raised:'signal',signal_raised:'signal',blocked:'wrong',look:'eye',travel:'done',beach:'eye'};const icon=aliases[cue]||cue;$('thought').innerHTML=items.length>1?items.map(id=>svg(id)).join('<span>+</span>'):svg(icon);$('thought').classList.add('show');clearTimeout(thoughtTimer);thoughtTimer=setTimeout(()=>$('thought').classList.remove('show'),2600);$('caption').textContent=text;$('caption').classList.toggle('show',prefs.captions);clearTimeout(captionTimer);captionTimer=setTimeout(()=>$('caption').classList.remove('show'),3500);}
function updatePlayer(){const node=$('player');node.style.left=player.x+'%';node.style.top=player.y+'%';node.style.setProperty('--scale',.8+(player.y-68)/70);}
function walkTo(x,y){const mine=++ticket,start={...player},dx=x-player.x,dy=y-player.y,duration=prefs.reduced?0:Math.min(1900,Math.max(240,Math.hypot(dx,dy)*27));$('player').style.setProperty('--facing',dx>=0?1:-1);$('player').classList.add('walking');const started=performance.now();return new Promise(resolve=>{function tick(now){if(mine!==ticket){resolve(false);return;}const t=duration?Math.min(1,(now-started)/duration):1;player={x:start.x+dx*t,y:start.y+dy*t};updatePlayer();if(t<1)requestAnimationFrame(tick);else{$('player').classList.remove('walking');resolve(true);}}requestAnimationFrame(tick);});}
function cancelWalk(){ticket++;$('player').classList.remove('walking');}
function flyItem(id,origin){if(prefs.reduced)return;const item=$('inventory').querySelector(`[data-item="${id}"]`);if(!item)return;const r=item.getBoundingClientRect(),s=$('scene').getBoundingClientRect(),x=s.left+s.width*(origin?.x||player.x)/100,y=s.top+s.height*(origin?.y||player.y)/100;const el=document.createElement('div');el.className='cursor-item flying';el.style.cssText=`display:block;left:${x}px;top:${y}px;width:44px;height:44px`;el.innerHTML=svg(id);document.body.appendChild(el);const animation=el.animate([{transform:'translate(-22px,-22px) scale(1.4)',opacity:1},{transform:`translate(${r.left-x+10}px,${r.top-y+10}px) scale(.75)`,opacity:.8}],{duration:650,easing:'ease-in-out'});animation.onfinish=()=>el.remove();}
function apply(response,origin){const wasDone=state.completed;state=response.state;if(selected&&!state.inventory.includes(selected))selected=null;save();render();showCue(response.cue,response.text,response.gained);response.gained.forEach(id=>flyItem(id,origin));if(!wasDone&&state.completed){finalShown=true;completionTimer=setTimeout(()=>{if(state.completed)$('completion').hidden=false;},prefs.reduced?0:1800);}}
async function activate(target,inspect=false){$('first-hint').hidden=true;const item=selected;const arrived=await walkTo(Math.max(14,Math.min(87,target.x-5)),Math.max(75,Math.min(86,target.y+12)));if(!arrived)return;$('player').classList.add('acting');setTimeout(()=>$('player').classList.remove('acting'),520);const r=inspect?E.interact(state,target.id,'look'):item?E.useItem(state,item,target.id):E.interact(state,target.id,target.kind==='person'?'talk':'use');apply(r,target);}
async function exitScene(exit){$('first-hint').hidden=true;if(!await walkTo(exit.x<50?5:95,83))return;cancelWalk();$('arrival').classList.add('cover');const response=E.travel(state,exit.to);state=response.state;player={x:exit.x<50?84:16,y:84};save();render();setTimeout(()=>$('arrival').classList.remove('cover'),prefs.reduced?0:240);}
function targetArt(t){if(t.kind==='person')return person(t.id);if(t.id==='sail')return svg('canvas');if(t.id==='driftwood'&&state.flags.woodCut)return '';if(['rope','pole','prybar','cairn','driftwood'].includes(t.id))return svg(t.id);return '';}
function dimensions(t){if(t.kind==='person')return[8.5,t.id==='henry'?25.5:27];return{rope:[6.5,9],pole:[12,12],prybar:[6,13],sail:[10,14],driftwood:[15,14],crate:[18,23],shelter:[35,43],hearth:[20,18],cairn:[7,11]}[t.id]||[8,12];}
function worldChanges(){const f=state.flags;let html='';
 if(state.scene==='beach'&&f.woodCut)html+=`<div class="change ground-prop" style="left:32%;top:56%;width:12%;height:10%">${svg('firewood')}</div>`;
 if(state.scene==='camp'){
 if(f.firewoodPlaced&&!f.fireLit)html+=`<div class="change ground-prop" style="left:27%;top:67%;width:11%;height:10%">${svg('firewood')}</div>`;
 if(f.fireLit)html+=`<div class="fire-glow" style="left:6%;top:39%"></div><div class="change painted-fire" style="left:27%;top:54%;width:10%;height:29%">${painted(A.states.fire,'flame')}</div>`;
 if(f.mastRaised)html+=`<div class="change signal-mast" style="left:44.4%;top:32%;width:6.1%;height:34%">${painted(f.signalRaised?A.states.mastFlag:A.states.mast,f.signalRaised?'flag-cloth':'bare-mast')}</div>`;
 if(state.completed)html+=[['musgrave',43,74,25.5],['raynal',73,76,27],['george',84,79,28]].map(([id,x,y,h])=>`<div class="change companion person" style="left:${x}%;top:${y-h/2}%;width:8.5%;height:${h}%;--actor-delay:-${x/17}s">${person(id)}</div>`).join('');
 }
 $('world-changes').innerHTML=html;
}
function renderInventory(){const empty=Math.max(0,8-state.inventory.length);$('inventory').innerHTML=state.inventory.map(id=>`<button class="item ${id===selected?'selected':''}" data-item="${id}" aria-label="${esc(E.ITEMS[id].name)}" aria-pressed="${id===selected}" title="${esc(E.ITEMS[id].name)}">${svg(id)}</button>`).join('')+Array.from({length:empty},()=>'<div class="item empty" aria-hidden="true"></div>').join('');$('inventory').querySelectorAll('[data-item]').forEach(b=>{const id=b.dataset.item;b.onclick=()=>{cancelWalk();if(selected&&selected!==id){const response=E.combine(state,selected,id);if(response.changed){selected=null;apply(response);}else{showCue('wrong',response.text);setSelected(id);}}else setSelected(selected===id?null:id);};b.onmouseenter=()=>label(selected&&selected!==id?`${E.ITEMS[selected].name} + ${E.ITEMS[id].name}`:E.ITEMS[id].name);b.onmouseleave=()=>label(selected?E.ITEMS[selected].name+' → …':E.SCENES.find(s=>s.id===state.scene).name);b.oncontextmenu=e=>{e.preventDefault();showCue(id,E.ITEMS[id].description);};});}
function render(){const scene=E.SCENES.find(s=>s.id===state.scene);$('scene').dataset.scene=state.scene;$('scene').dataset.shelter=String(state.flags.shelterBuilt);$('scene').dataset.crate=String(state.flags.crateOpen);$('scene').classList.toggle('warm',state.scene==='camp'&&state.flags.fireLit);$('scene').setAttribute('aria-label',scene.name);$('scene-label').textContent=scene.name;$('goals').innerHTML=[['shelter','shelterBuilt','Přístřeší'],['fire','fireLit','Oheň'],['signal','signalRaised','Signál']].map(([icon,flag,name])=>`<span class="goal ${state.flags[flag]?'done':''}" title="${name}" aria-label="${name}: ${state.flags[flag]?'hotovo':'zbývá'}">${svg(icon)}</span>`).join('');
 $('targets').innerHTML=E.getTargets(state).map(t=>{const [w,h]=dimensions(t);const y=t.kind==='person'?(t.id==='henry'?76:75)-h/2:t.y;return `<button class="target ${t.kind==='item'?'pickup':t.kind}" style="left:${t.x}%;top:${y}%;--w:${w}%;--h:${h}%;--actor-delay:-${t.x/17}s" data-target="${t.id}" aria-label="${esc(t.name)}" title="${esc(t.name)}">${targetArt(t)}</button>`;}).join('');
 $('targets').querySelectorAll('[data-target]').forEach(b=>{const t=E.getTargets(state).find(x=>x.id===b.dataset.target);b.onclick=e=>{e.stopPropagation();activate(t);};b.oncontextmenu=e=>{e.preventDefault();e.stopPropagation();activate(t,true);};b.onmouseenter=()=>label(selected?`${E.ITEMS[selected].name} → ${t.name}`:t.name);b.onmouseleave=()=>label(selected?E.ITEMS[selected].name+' → …':scene.name);});
 $('exits').innerHTML=scene.exits.map(e=>`<button class="exit" style="left:${e.x}%;top:${e.y}%" data-exit="${e.id}" title="${e.name}" aria-label="${e.name}">${e.x<50?'‹':'›'}</button>`).join('');$('exits').querySelectorAll('[data-exit]').forEach(b=>b.onclick=e=>{e.stopPropagation();exitScene(scene.exits.find(x=>x.id===b.dataset.exit));});
 worldChanges();renderInventory();updatePlayer();$('cancel-item').hidden=!selected;$('cursor-item').innerHTML=selected?svg(selected):'';$('cursor-item').style.display=selected?'block':'none';label(selected?E.ITEMS[selected].name+' → …':scene.name);
}
function modal(title,html){cancelWalk();$('modal-title').textContent=title;$('modal-body').innerHTML=html;if(!$('modal').open)$('modal').showModal();}
function help(){modal('Ruce místo odstavců',`<div class="pictogram-help"><div><strong>☝ →</strong><p>Klikni do scény.<br>Postava dojde na místo.</p></div><div><strong>☝ ↓ ▣</strong><p>Klikni na věc.<br>Vezmeš ji nebo prozkoumáš.</p></div><div><strong>▣ + ▣</strong><p>Vyber předmět v brašně,<br>pak druhý předmět.</p></div><div><strong>▣ → ◉</strong><p>Vyber předmět,<br>pak místo ve scéně.</p></div></div><p class="small">Pravé tlačítko prohlédne předmět. Esc odloží výběr. Mezerník krátce ukáže aktivní místa. Tab a Enter také fungují. Krátké textové reakce lze zapnout v nastavení.</p>`);}
function hint(){const h=E.hint(state),target=E.SCENES.find(s=>s.id===h.sceneId).targets.find(t=>t.id===h.targetId);const targetIcon={sail:'canvas',shelter:'shelter',hearth:'fire',crate:'crate',driftwood:'driftwood',cairn:'signal'}[h.targetId]||h.targetId;modal('Malá nápověda',h.cue==='combine'?`<div class="hint-icons">${svg('rope')}<span>+</span>${svg('pole')}<span>→</span>${svg('loopPole')}</div>`:`<div class="hint-icons">${svg(h.itemId||(h.cue==='take'?'hand':h.cue))}<span>→</span>${svg(targetIcon)}</div><p style="text-align:center">${E.SCENES.find(s=>s.id===h.sceneId).name}</p>`);if(prefs.captions)$('modal-body').insertAdjacentHTML('beforeend',`<p class="small">${esc(h.text)}</p>`);}
function settings(){modal('Nastavení',`<div class="setting"><span>Krátké titulky reakcí</span><button id="toggle-captions">${prefs.captions?'Zapnuté':'Vypnuté'}</button></div><div class="setting"><span>Animace</span><button id="toggle-motion">${prefs.reduced?'Omezené':'Zapnuté'}</button></div><div class="setting"><span>Začít od břehu</span><button id="restart">Nová hra</button></div><p class="small">Toto je první hratelná kapitola nové adventury. Předmětové hádanky, postava a malby jsou fikce inspirovaná skutečným příběhem Graftonu. Neukazují přesný průběh první noci. Malby vznikly pomocí AI.</p><p class="small"><a href="https://github.com/OnFiala/auckland-castaways/tree/main/adventure" target="_blank" rel="noopener noreferrer">Prameny a soubory projektu ↗</a></p>`);$('toggle-captions').onclick=()=>{prefs.captions=!prefs.captions;savePrefs();settings();};$('toggle-motion').onclick=()=>{prefs.reduced=!prefs.reduced;savePrefs();settings();};$('restart').onclick=restart;}
function restart(){modal('Znovu na břeh?',`<p class="small">Nahradí se rozehraný postup této adventury.</p><button class="dialog-button" id="confirm-restart">Začít znovu</button>`);$('confirm-restart').onclick=()=>{cancelWalk();clearTimeout(completionTimer);state=E.createGame();selected=null;player={x:45,y:84};finalShown=false;$('completion').hidden=true;$('modal').close();save();render();$('scene').focus();};}
function reveal(){document.body.classList.add('show-targets');clearTimeout(revealTimer);revealTimer=setTimeout(()=>document.body.classList.remove('show-targets'),2400);}
$('scene').onclick=e=>{if(e.target.closest('button'))return;$('first-hint').hidden=true;const r=$('scene').getBoundingClientRect();walkTo(Math.max(6,Math.min(94,(e.clientX-r.left)/r.width*100)),Math.max(74,Math.min(90,(e.clientY-r.top)/r.height*100)));};
$('scene').oncontextmenu=e=>e.preventDefault();$('hint').onclick=hint;$('reveal').onclick=reveal;$('settings').onclick=settings;$('help').onclick=help;$('cancel-item').onclick=()=>{cancelWalk();setSelected(null);};$('modal-close').onclick=()=>$('modal').close();$('dismiss-hint').onclick=()=>$('first-hint').hidden=true;$('keep-exploring').onclick=()=>$('completion').hidden=true;$('new-game').onclick=restart;
window.addEventListener('pointermove',e=>{$('cursor-item').style.left=e.clientX+14+'px';$('cursor-item').style.top=e.clientY+12+'px';});window.addEventListener('keydown',e=>{if(e.key==='Escape'){cancelWalk();setSelected(null);}if(e.code==='Space'&&!$('modal').open&&!e.target.closest('button')){e.preventDefault();reveal();}});
$('rain').innerHTML=Array.from({length:28},(_,i)=>`<i style="--x:${i*37%110}%;--speed:${.8+i%5*.12}s;--delay:-${i*.17}s"></i>`).join('');
savePrefs();save();render();if(state.actions>0)$('first-hint').hidden=true;
})();
